using CarArchive.Core;
static class BuiltInNamingTests {
 public static void Register(Action<string,Func<Task>> test) {
  test("Portable guide covers live inventory without archive access",()=>{var g=BuiltInNamingGuide.Load();if(g.Inventory.Count<1900||g.Notes.Count!=8||g.Inventory.Any(x=>Path.IsPathRooted(x.Path)))throw new Exception("portable coverage");var s=new NamingService();var state=new WorkspaceState();state.Settings.ArchiveRoot="Z:/nonexistent";if(!s.Suggest(new(){Brand="Ferrari",Series="SF90",Variant="SF90 Spider",Generation="1st"},state,[]).Name.Equals("SF90 Spider"))throw new Exception("Ferrari");return Task.CompletedTask;});
  test("Automatic brand resolution rejects poisoned mappings and separates Mercedes divisions",()=>{var s=new NamingService();var w=new WorkspaceState();w.BrandFolders["Audi"]="BMW";w.BrandFolders["Mercedes-Benz"]="Mercedes-AMG";if(s.ResolveBrand(new CarIdentity{Brand="Audi"},w)!="Audi"||s.ResolveBrand(new CarIdentity{Brand="Mercedes-Benz",Variant="C-Class AMG-Line"},w)!="Mercedes-Benz"||s.ResolveBrand(new CarIdentity{Brand="Mercedes-Benz",OfficialName="Mercedes-AMG C 63"},w)!="Mercedes-AMG")throw new Exception("wrong brand");return Task.CompletedTask;});
  test("Explicit supplemental policies remain independent of existing directories",()=>{var s=new NamingService();var w=new WorkspaceState();foreach(var c in new[]{(new CarIdentity{Brand="Mercedes-Benz",Series="S-Class",Variant="S 500 4MATIC",Code="W223"},"S-Class S500 (W223)"),(new CarIdentity{Brand="Mercedes-Maybach",Series="S-Class",Variant="S 580",Code="Z223"},"S-Class S580 (Z223)"),(new CarIdentity{Brand="Porsche",Series="718",Variant="718 Cayman GT4",Code="982"},"718 Cayman GT4 (982)"),(new CarIdentity{Brand="Porsche",Series="911",Variant="911 Carrera",Code="992",Phase="Facelift"},"911 Carrera (992.2)")}){var n=s.Suggest(c.Item1,w,[]).Name;if(n!=c.Item2)throw new Exception(n+" != "+c.Item2);}return Task.CompletedTask;});
 }
}
